import {uid,today,addActivity,initBilling} from './domain.js';
import {validateInvoiceDesign,defaultInvoiceDesign} from './invoice-design.js';
const clean=x=>String(x??'').trim();
const validDate=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(Date.parse(d))&&new Date(d).toISOString().slice(0,10)===d;
export function calculateInvoice(items,taxRate=0){
 if(!Array.isArray(items)||!items.length||items.length>30)throw Error('Add between 1 and 30 line items.');
 const lines=items.map(item=>{const description=clean(item.description),quantity=Number(item.quantity),rate=Number(item.rate);if(!description||description.length>300)throw Error('Add a description to each line item (up to 300 characters).');if(!Number.isFinite(quantity)||quantity<=0||quantity>100000||Math.abs(quantity*100-Math.round(quantity*100))>0.00001)throw Error('Use positive quantities with up to two decimal places.');if(!Number.isSafeInteger(rate)||rate<0||rate>100000000)throw Error('Enter a valid unit price.');const amount=Math.round(quantity*rate);if(!Number.isSafeInteger(amount))throw Error('Line item amount is too large.');return {description,quantity,rate,amount};});
 const subtotal=lines.reduce((n,l)=>n+l.amount,0),tax=Number(taxRate);if(!Number.isFinite(tax)||tax<0||tax>100||Math.abs(tax*100-Math.round(tax*100))>0.00001)throw Error('Enter a tax rate between 0 and 100, with up to two decimal places.');const taxAmount=Math.round(subtotal*tax/100),amount=subtotal+taxAmount;if(!Number.isSafeInteger(amount)||amount<1||amount>10000000000)throw Error('Invoice total must be between $0.01 and $100,000,000.');return {items:lines,subtotal,taxRate:tax,taxAmount,amount};
}
export function saveInvoiceDefaults(s,data){const design=validateInvoiceDesign(data);s.settings.invoiceDesign=design;addActivity(s,'Invoice template updated','Applies to new invoices','document');return design;}
export function prepareInvoice(s,data){
 const c=s.clients.find(c=>c.id===data.clientId&&!c.archived);if(!c)throw Error('Choose an active client.');const p=data.projectId?s.projects.find(p=>p.id===data.projectId):null;if(data.projectId&&(!p||p.archived||p.status==='cancelled'||p.clientId!==c.id))throw Error('Choose an active project belonging to this client.');
 const issued=clean(data.issued),due=clean(data.due);if(!validDate(issued)||!validDate(due)||due<issued)throw Error('Choose valid dates, with the due date on or after the issue date.');const notes=clean(data.notes),paymentInstructions=clean(data.paymentInstructions),billingAddress=clean(data.billingAddress);if(notes.length>2000||paymentInstructions.length>3000||billingAddress.length>1000)throw Error('Shorten the notes, payment instructions, or billing address.');
 return {...calculateInvoice(data.items,data.taxRate),projectId:p?.id||null,clientId:c.id,clientName:c.name,clientEmail:c.email,projectName:p?.name||'',business:s.settings.business,issued,due,notes,paymentInstructions,billingAddress,design:validateInvoiceDesign(data.design||s.settings.invoiceDesign||defaultInvoiceDesign()),kind:'manual',label:'Services',paid:0,payments:[]};
}
export function createManualInvoice(s,data,key){if(!key)throw Error('Invoice operation identifier required.');const existing=s.invoices.find(i=>i.creationKey===key);if(existing)return existing;const draft=prepareInvoice(s,data);initBilling(s);const number=`INV-${String(Math.max(0,...s.invoices.map(i=>Number(i.number.split('-')[1])||0))+1).padStart(3,'0')}`,i={...draft,id:uid(),number,creationKey:key,createdAt:new Date().toISOString()};s.invoices.unshift(i);addActivity(s,'Invoice created',`${number} · ${i.clientName}`,'document');return i;}
